import {createGardenState} from '../../../../src/js/garden/GardenSimulation.js';
import {GARDEN_ART} from '../../../../src/js/garden/GardenArt.js';
import {gardenPlatforms} from '../../../../src/js/garden/GardenLevel.js';
import {ToyRoomPhase} from '../../../../src/js/toy-room/ToyRoomPhase.js';
const check=(value,label)=>{if(!value)throw Error(label);};
const wait=ms=>new Promise(r=>setTimeout(r,ms));
async function prepared(phase){for(let i=0;i<200&&!phase.ready;i++){if(phase.error)throw Error(phase.error);await wait(50);}check(phase.ready,'Artes do jardim prontas');}
/** Usa o host real, não uma cópia do renderer, e deixa a simulação pausada entre amostras. */
export async function start(difficulty='NORMAL'){
 const g=review.game;await g.assetsReady;g.startDebugPhase('garden',difficulty);const phase=g.state.toyRoomInstance.instance.garden;await prepared(phase);g.setPaused(true);phase.state.stage='RUNNING';phase.state.age=5;return true;
}
export async function audit(){
 const g=review.game,r=g.state.toyRoomInstance.instance,phase=r.garden,renderer=phase.renderer,shots=[];
 let frames=0;for(const [key,set]of Object.entries(GARDEN_ART.sets)){
  const image=renderer.images.get(set.file);check(image,'Arte carregada: '+set.file);const canvas=document.createElement('canvas');canvas.width=image.width;canvas.height=image.height;const ctx=canvas.getContext('2d');ctx.drawImage(image,0,0);const pixels=ctx.getImageData(0,0,canvas.width,canvas.height).data;
  for(const frame of set.frames){let opaque=0,transparent=0,bottom=0;for(let y=0;y<frame.h;y++)for(let x=0;x<frame.w;x++){const alpha=pixels[((frame.y+y)*canvas.width+frame.x+x)*4+3];if(alpha>128)opaque++;if(alpha===0)transparent++;if(alpha)bottom=y+1;}check(opaque>100,'Objeto/pose visível');if(key!=='objetos'){check(transparent>100,'Pose realmente transparente');check(bottom===frame.anchorY,'Pés registrados no alfa real');}frames++;}
 }
 const snapshot=JSON.stringify(phase.state);phase.render();check(snapshot===JSON.stringify(phase.state),'Render não altera o estado');const base=renderer.frame(phase.state);const y=phase.state.player.y;phase.state.player.y-=150;const jump=renderer.frame(phase.state);phase.state.player.y=y;check(base.scale===jump.scale&&base.oy===jump.oy,'Altura e escala da câmera independem do pulo');
 for(const [label,x]of [['entrada',160],['madeira',1570],['lagarta',2300],['pedras',3700],['roda',5000],['arvore',7460]]){
  phase.state=createGardenState();phase.state.stage=label==='arvore'?'COMPLETE':'RUNNING';phase.state.age=label==='arvore'?3:5;phase.state.time=10;
  const support=gardenPlatforms(10).filter(p=>x>=p.x&&x<=p.x+p.w).sort((a,b)=>a.y-b.y)[0];Object.assign(phase.state.player,{x,y:support?.y??590,onGround:true,support:support?.id??null});phase.render();shots.push({label,data:phase.canvas.toDataURL()});
 }
 // Transição real da campanha ao concluir a perseguição e restauração do jardim.
 const canvas=document.createElement('canvas');canvas.width=960;canvas.height=540;
 const room=new ToyRoomPhase(canvas,null,null,null,{assets:g.assets,bindInputs:false});room.story.state.arenaCompleted=true;room.arena.state.completed=true;room.tutorial.finish();let chaseDestroyed=0;
 room.chase={active:true,campaign:true,state:{stage:'COMPLETE'},update(){},destroy(){chaseDestroyed++;}};room.update(150);check(room.garden?.active&&chaseDestroyed===1,'Fim da campanha abre o jardim e descarta o 3D');await prepared(room.garden);
 room.garden.state.stage='RUNNING';room.garden.state.player.x=2250;room.garden.state.checkpoint=2150;const saved=room.snapshot();check(saved.toyRoomGarden&&!saved.toyRoomChaseCampaign,'Save só contém o jardim ativo');room.restore(saved);await prepared(room.garden);check(room.garden.state.player.x===2250&&room.garden.state.checkpoint===2150,'Restore retoma posição e checkpoint');
 const before=room.garden.snapshot();room.garden.setPaused(true);room.garden.update(30);check(JSON.stringify(before)===JSON.stringify(room.garden.snapshot()),'Pausa não avança relógio/física');room.garden.setPaused(false);
 const audio=room.garden.audio;room.garden.state.stage='GAME_OVER';check(room.retryDefeat(),'Retry do host retoma o jardim');check(room.garden.state.player.x===2150&&room.garden.state.hp===3,'Retry no checkpoint e vidas restauradas');const disposed=room.garden;room.destroy();check(!disposed.input.installed&&disposed.renderer.images.size===0&&audio.voices.size===0,'Listeners, imagens e vozes liberados');
 return {frames,shots,transition:true,save:true,pause:true,dispose:true};
}
export async function traverse(difficulty){
 const {gardenPilot}=await import('./piloto.mjs');const g=review.game,phase=g.state.toyRoomInstance.instance.garden;
 phase.difficulty=difficulty;phase.state=createGardenState(difficulty);const sample=phase.input.sample,event=phase.audio.event,update=phase.audio.update;phase.input.sample=()=>gardenPilot(phase.state);phase.audio.event=()=>{};phase.audio.update=()=>{};
 g.setPaused(false);let ticks=0,falls=0;try{while(!['COMPLETE','GAME_OVER'].includes(phase.state.stage)&&ticks++<10000){phase.update(1);if(ticks%300===0)phase.render();}phase.render();check(phase.state.stage==='COMPLETE','Travessia real do host chega à árvore');return{difficulty,ticks,hp:phase.state.hp,stage:phase.state.stage,defeated:phase.state.defeated};}finally{g.setPaused(true);phase.input.sample=sample;phase.audio.event=event;phase.audio.update=update;}
}
export function controls(){const phase=review.game.state.toyRoomInstance.instance.garden,canvas=phase.canvas,rect=canvas.getBoundingClientRect();return Object.fromEntries(Object.entries(phase.renderer.controls()).map(([key,b])=>[key,{x:rect.left+b.x/canvas.width*rect.width,y:rect.top+b.y/canvas.height*rect.height}]));}
